-- Migration: 0011_create_students_table.sql
-- Created: 2026-08-14
-- Description: The central student entity. Every module references this table.
-- Related documents: Official Documentation/01 Foundation Layer/DATABASE.md — students table
--                    Official Documentation/07 Student and Parent Modules/STUDENTS.md

-- === MIGRATION START ===

CREATE TABLE IF NOT EXISTS public.students (
  id                    UUID DEFAULT gen_random_uuid() PRIMARY KEY,

  student_id            TEXT UNIQUE NOT NULL,
  -- Format: STU-ZM-LSK-0001-00042. Generated by the student creation Edge
  -- Function. Never manually assigned.

  school_id             UUID NOT NULL REFERENCES public.schools(id),
  clerk_user_id         TEXT,
  -- Populated when a student creates a ZSMS login. NULL otherwise.

  first_name            TEXT NOT NULL,
  last_name             TEXT NOT NULL,
  date_of_birth         DATE,
  gender                TEXT CHECK (gender IN ('male', 'female', 'not_stated')),

  nrc_or_birth_cert     TEXT,
  -- Encrypted at the application layer before storage. Never returned in
  -- standard student API responses.

  photo_url             TEXT,

  enrolment_date        DATE NOT NULL DEFAULT CURRENT_DATE,

  grade_id              TEXT NOT NULL,
  -- Matches school_grade_levels.level_id. Deliberately not a foreign key:
  -- DATABASE.md defines it as free TEXT so a school can reorganise its grade
  -- structure without rewriting student rows.

  class_id              TEXT NOT NULL,

  is_boarding           BOOLEAN NOT NULL DEFAULT FALSE,

  status                TEXT NOT NULL DEFAULT 'active'
                        CHECK (status IN (
                          'active', 'on_leave', 'transferred', 'graduated', 'withdrawn'
                        )),

  is_deleted            BOOLEAN NOT NULL DEFAULT FALSE,
  deleted_at            TIMESTAMPTZ,
  deleted_by            TEXT,
  -- Soft delete only. Hard deletes on students are forbidden
  -- (CONVENTIONS.md prohibition 8), which is why no DELETE policy or
  -- DELETE privilege is ever granted on this table.

  created_at            TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at            TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

COMMENT ON COLUMN public.students.is_deleted IS
  'Soft delete flag. Hard deletes are prohibited on students (CONVENTIONS.md prohibition 8).';

CREATE INDEX IF NOT EXISTS idx_students_school_id     ON public.students(school_id);
CREATE INDEX IF NOT EXISTS idx_students_school_status ON public.students(school_id, status);
CREATE INDEX IF NOT EXISTS idx_students_school_grade  ON public.students(school_id, grade_id);
CREATE INDEX IF NOT EXISTS idx_students_school_class  ON public.students(school_id, class_id);
CREATE INDEX IF NOT EXISTS idx_students_student_id    ON public.students(student_id);
CREATE INDEX IF NOT EXISTS idx_students_clerk_user
  ON public.students(clerk_user_id) WHERE clerk_user_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_students_fulltext ON public.students
  USING GIN(to_tsvector('english', first_name || ' ' || last_name));

DROP TRIGGER IF EXISTS update_timestamp_on_students ON public.students;
CREATE TRIGGER update_timestamp_on_students
  BEFORE UPDATE ON public.students
  FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

REVOKE ALL ON public.students FROM anon;
GRANT SELECT, INSERT, UPDATE ON public.students TO authenticated;

-- RLS is applied in 0016, after staff_permission_grants exists — the student
-- policies call has_permission_grant(), which reads that table.

-- === MIGRATION END ===
